// --- samp_mdb.Project.c_high_priority_task.Find
// Look up row by row id. Return NULL if out of range
inline samp_mdb::Task* samp_mdb::c_high_priority_task_Find(samp_mdb::Project& project, u32 t) {
    samp_mdb::Task *retval = NULL;
    u64 idx = t;
    u64 lim = project.c_high_priority_task_n;
    if (idx < lim) {
        retval = project.c_high_priority_task_elems[idx];
    }
    return retval;
}

// --- samp_mdb.Project.c_high_priority_task.Getary
// Return array of pointers
inline algo::aryptr<samp_mdb::Task*> samp_mdb::c_high_priority_task_Getary(samp_mdb::Project& project) {
    return algo::aryptr<samp_mdb::Task*>(project.c_high_priority_task_elems, project.c_high_priority_task_n);
}

