inline samp_mdb::Task& samp_mdb::c_high_priority_task_qFind(samp_mdb::Project& project, u32 idx) {
    return *project.c_high_priority_task_elems[idx];
}

// --- samp_mdb.Project.c_high_priority_task.qLast
// Reference to last element without bounds checking
inline samp_mdb::Task& samp_mdb::c_high_priority_task_qLast(samp_mdb::Project& project) {
    return *project.c_high_priority_task_elems[project.c_high_priority_task_n-1];
}

// --- samp_mdb.Project..Init
// Set all fields to initial values.
inline void samp_mdb::Project_Init(samp_mdb::Project& project) {
    project.zd_task_head = NULL; // (samp_mdb.Project.zd_task)
    project.zd_task_n = 0; // (samp_mdb.Project.zd_task)
    project.zd_task_tail = NULL; // (samp_mdb.Project.zd_task)
    project.c_high_priority_task_elems = NULL; // (samp_mdb.Project.c_high_priority_task)
    project.c_high_priority_task_n = 0; // (samp_mdb.Project.c_high_priority_task)
    project.c_high_priority_task_max = 0; // (samp_mdb.Project.c_high_priority_task)
    project.project_next = (samp_mdb::Project*)-1; // (samp_mdb.FDb.project) not-in-tpool's freelist
    project.ind_project_next = (samp_mdb::Project*)-1; // (samp_mdb.FDb.ind_project) not-in-hash
    project.ind_project_hashval = 0; // stored hash value
    project.zd_project_next = (samp_mdb::Project*)-1; // (samp_mdb.FDb.zd_project) not-in-list
    project.zd_project_prev = NULL; // (samp_mdb.FDb.zd_project)
}

