// --- samp_mdb.Project.c_high_priority_task_curs.Reset
inline void samp_mdb::project_c_high_priority_task_curs_Reset(project_c_high_priority_task_curs &curs, samp_mdb::Project &parent) {
    curs.elems = parent.c_high_priority_task_elems;
    curs.n_elems = parent.c_high_priority_task_n;
    curs.index = 0;
}

// --- samp_mdb.Project.c_high_priority_task_curs.ValidQ
// cursor points to valid item
inline bool samp_mdb::project_c_high_priority_task_curs_ValidQ(project_c_high_priority_task_curs &curs) {
    return curs.index < curs.n_elems;
}

// --- samp_mdb.Project.c_high_priority_task_curs.Next
// proceed to next item
inline void samp_mdb::project_c_high_priority_task_curs_Next(project_c_high_priority_task_curs &curs) {
    curs.index++;
}

