// --- samp_mdb.Task..Init
// Set all fields to initial values.
inline void samp_mdb::Task_Init(samp_mdb::Task& task) {
    task.priority = i32(0);
    task.task_next = (samp_mdb::Task*)-1; // (samp_mdb.FDb.task) not-in-tpool's freelist
    task.ind_task_next = (samp_mdb::Task*)-1; // (samp_mdb.FDb.ind_task) not-in-hash
    task.ind_task_hashval = 0; // stored hash value
    task.zd_task_next = (samp_mdb::Task*)-1; // (samp_mdb.FDb.zd_task) not-in-list
    task.zd_task_prev = NULL; // (samp_mdb.FDb.zd_task)
    task.bh_task_idx = -1; // (samp_mdb.FDb.bh_task) not-in-heap
    task.zd_task_priority_next = (samp_mdb::Task*)-1; // (samp_mdb.FDb.zd_task_priority) not-in-list
    task.zd_task_priority_prev = NULL; // (samp_mdb.FDb.zd_task_priority)
    task.project_zd_task_next = (samp_mdb::Task*)-1; // (samp_mdb.Project.zd_task) not-in-list
    task.project_zd_task_prev = NULL; // (samp_mdb.Project.zd_task)
    task.user_zd_task_next = (samp_mdb::Task*)-1; // (samp_mdb.User.zd_task) not-in-list
    task.user_zd_task_prev = NULL; // (samp_mdb.User.zd_task)
}

